def main():
    import sys
    import threading

    def find_cycle(graph, start, visited, parent):
        visited[start] = True
        for neighbor in graph[start]:
            if not visited[neighbor]:
                if find_cycle(graph, neighbor, visited, start):
                    return True
            elif neighbor != parent:
                return True
        return False

    def dfs(graph, start, visited, component):
        stack = [start]
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                component.append(node)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)

    def find_connected_components(graph, n):
        visited = [False] * (n + 1)
        components = []
        for i in range(1, n + 1):
            if not visited[i]:
                component = []
                dfs(graph, i, visited, component)
                components.append(component)
        return components

    def play_game(n, m, edges):
        graph = [[] for _ in range(n + 1)]
        for v, u in edges:
            graph[v].append(u)
            graph[u].append(v)

        # Place bees in the first three vertices
        print("1 2 3")
        sys.stdout.flush()
        nastya_pos = int(input().strip())

        # Simple strategy: move bees towards Nastya
        bees_pos = [1, 2, 3]
        for _ in range(n):
            next_moves = []
            for bee in bees_pos:
                if bee == nastya_pos:
                    print(" ".join(map(str, bees_pos)))
                    return
                min_dist = float('inf')
                next_pos = bee
                for neighbor in graph[bee]:
                    dist = abs(neighbor - nastya_pos)
                    if dist < min_dist:
                        min_dist = dist
                        next_pos = neighbor
                next_moves.append(next_pos)
            bees_pos = next_moves
            print(" ".join(map(str, bees_pos)))
            sys.stdout.flush()
            nastya_pos = int(input().strip())
            if any(bee == nastya_pos for bee in bees_pos):
                return

    n, m = map(int, input().strip().split())
    edges = [tuple(map(int, input().strip().split())) for _ in range(m)]
    play_game(n, m, edges)

threading.Thread(target=main).start()
